import { Address, toNano } from '@ton/core';
import { useState } from 'react';
import { useParams } from 'react-router';
import { DIRECT_VESTING_CONTRACTS } from '../constants';
import { DirectVestingContract } from '../contracts';
import { tonClientSelector } from '../state';
import { RouteParams } from '../types';
import { delay, getAddress, waitForSeqno } from '../utils';
import { useLoadable } from './useLoadable';
import { useTonConnect } from './useTonConnect';

export function useTerminateContract() {
  const { address } = useParams<RouteParams>();
  const { sender, wallet } = useTonConnect();
  const [sendingTx, setSendingTx] = useState(false);
  const [closeForm, setCloseForm] = useState(false);
  const client = useLoadable(tonClientSelector);

  return {
    sendingTx,
    closeForm,
    sendAction: async () => {
      if (!client || !wallet || !address) {
        return;
      }
      if (!DIRECT_VESTING_CONTRACTS[address]) return;
      const vesingAddr = getAddress(DIRECT_VESTING_CONTRACTS[address]);

      if (!vesingAddr) {
        return;
      }
      setSendingTx(true);
      const waiter = await waitForSeqno(client, Address.parse(wallet));

      let senderFail = false;
      try {
        await sender?.send({
          to: vesingAddr,
          value: toNano(0.1),
          body: DirectVestingContract.terminateMessage(),
        });
      } catch (error) {
        senderFail = true;
      }

      if (senderFail) {
        return setSendingTx(false);
      }

      try {
        await waiter();
        await delay(10 * 1000);
      } catch (error) {}

      setSendingTx(false);
      setCloseForm(true);
    },
  };
}
