import { Check, InfoOutlined } from '@mui/icons-material';
import {
  Button,
  Card,
  CardContent,
  DialogContent,
  DialogTitle,
  FormControl,
  FormHelperText,
  FormLabel,
  IconButton,
  Input,
  Modal,
  ModalDialog,
  Skeleton,
  Stack,
  Tooltip,
  Typography,
} from '@mui/joy';
import { FormEvent, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { DEFAULT_DECIMAL_PLACES, NOW } from '/src/constants';
import { useWithdrawStake } from '/src/hooks';
import { Asset, JettonWalletItem } from '/src/types';
import { fromUnits, toUnits } from '/src/units';

type Props = {
  open: boolean;
  setOpen: (v: boolean) => void;
  staking?: Asset;
  stakingJetton?: JettonWalletItem;
  loading: boolean;
};

export const ModalEarnForm = ({ open, setOpen, staking, stakingJetton, loading }: Props) => {
  const { t } = useTranslation();
  const { amount, closeForm, setAmount, sendingTx, sendWithdraw } = useWithdrawStake(stakingJetton);
  const decimals = DEFAULT_DECIMAL_PLACES;
  const stakeBalance = useMemo(
    () => Number(fromUnits(stakingJetton?.balance.value || 0n, decimals)),
    [stakingJetton],
  );
  const estEarning = useMemo(() => {
    if (
      !stakingJetton?.balance.value ||
      !staking?.staking?.fixed_apy ||
      !stakingJetton?.balance.stakeAt
    )
      return;
    const day = 86400n;
    const diff = BigInt(NOW() - stakingJetton?.balance.stakeAt);
    const lockupTs = day * BigInt(staking?.staking.lockup);
    // const timePassed = lockupTs > diff ? 0n : diff;
    const timePassed = diff;
    const amountUnits = toUnits(amount, decimals);

    return {
      lockupNotPassed: lockupTs > diff,
      value: fromUnits(
        ((amountUnits * staking.staking.fixed_apy) / 100n / (365n * day)) * timePassed,
        decimals,
      ),
    };
  }, [staking, amount]);

  return (
    <Modal open={open} onClose={() => setOpen(false)}>
      <ModalDialog
        sx={(theme) => ({
          [theme.breakpoints.only('xs')]: {
            top: 0,
            bottom: 'unset',
            left: 0,
            right: 0,
            borderRadius: 0,
            transform: 'none',
            maxWidth: 'unset',
          },
        })}
      >
        <DialogTitle>{t('staking.form.title-earn')}</DialogTitle>
        <DialogContent>{t('staking.form.earn-description')}</DialogContent>
        <form
          onSubmit={(event: FormEvent<HTMLFormElement>) => {
            event.preventDefault();
            setOpen(false);
          }}
        >
          <Stack spacing={2}>
            <FormControl size="lg">
              <FormLabel sx={{ width: '100%' }}>
                <Stack
                  width="100%"
                  direction="row"
                  justifyContent="space-between"
                  alignItems="center"
                  gap={1}
                >
                  <Typography>{t('staking.form.amount')}</Typography>
                  <Stack direction="row" gap={1}>
                    <Typography
                      textColor="neutral.400"
                      sx={{ position: 'relative', overflow: 'hidden' }}
                    >
                      <Skeleton loading={loading}>
                        {t('staking.form.stake')}:{' '}
                        {(stakeBalance - Number(amount)).toLocaleString()}
                      </Skeleton>
                    </Typography>
                    <Button
                      disabled={
                        loading || closeForm || sendingTx || !stakeBalance || stakeBalance === 0
                      }
                      variant="soft"
                      sx={{ py: 0.1, px: 1, minHeight: 25 }}
                      onClick={() => setAmount(stakeBalance.toString())}
                    >
                      {t('staking.form.button-max')}
                    </Button>
                  </Stack>
                </Stack>
              </FormLabel>
              <Input
                disabled={
                  loading ||
                  closeForm ||
                  sendingTx ||
                  !stakeBalance ||
                  stakeBalance === 0 ||
                  !staking?.staking
                }
                autoFocus
                required
                endDecorator={staking?.value.content?.symbol}
                value={amount}
                onChange={(e) => {
                  const value = Number(e.currentTarget.value).toFixed();
                  const bigV = toUnits(value, decimals);
                  const realBalance = stakingJetton?.balance.value || 0n;
                  setAmount(bigV > realBalance ? stakeBalance.toString() : value);
                }}
              />
            </FormControl>
            <Card variant="soft" sx={{ width: '100%' }}>
              <CardContent sx={{ textAlign: 'center' }}>
                <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
                  <Tooltip title={t('staking.form.apy-info')} variant="solid">
                    <Typography
                      endDecorator={
                        <InfoOutlined color="secondary" sx={{ width: 18, height: 18 }} />
                      }
                    >
                      {t('staking.form.apy')}
                    </Typography>
                  </Tooltip>
                  <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
                    <Skeleton loading={loading}>
                      {staking?.staking?.fixed_apy.toLocaleString()}%
                    </Skeleton>
                  </Typography>
                </Stack>
                <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
                  <Typography>{t('staking.form.est-earning')}</Typography>
                  <Typography sx={{ position: 'relative', overflow: 'hidden' }}>
                    <Skeleton loading={loading}>
                      ~ {estEarning ? estEarning.value.toLocaleString() : '0'}
                    </Skeleton>
                  </Typography>
                </Stack>
                <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
                  <Typography>{t('staking.form.lockup-period')}</Typography>
                  <Typography
                    color={
                      estEarning ? (estEarning.lockupNotPassed ? 'warning' : 'success') : 'neutral'
                    }
                    sx={{ position: 'relative', overflow: 'hidden' }}
                  >
                    <Skeleton loading={loading}>
                      {estEarning
                        ? estEarning.lockupNotPassed
                          ? t('staking.form.lockup-not-passed')
                          : t('staking.form.lockup-passed')
                        : ''}
                    </Skeleton>
                  </Typography>
                </Stack>
              </CardContent>
            </Card>
            <FormHelperText sx={{ p: 0 }}>{t('staking.form.helper')}</FormHelperText>
            {closeForm ? (
              <IconButton color="success" onClick={() => setOpen(false)}>
                <Check />
              </IconButton>
            ) : (
              <Button
                size="lg"
                type="submit"
                loading={sendingTx}
                disabled={
                  loading ||
                  closeForm ||
                  !staking?.staking ||
                  !stakeBalance ||
                  stakeBalance === 0 ||
                  !amount ||
                  !Number(amount)
                }
                onClick={() => sendWithdraw()}
              >
                {t('staking.form.button-withdraw')}
              </Button>
            )}
          </Stack>
        </form>
      </ModalDialog>
    </Modal>
  );
};
