import {
  Alert,
  Button,
  DialogActions,
  Divider,
  FormControl,
  FormLabel,
  Input,
  Modal,
  ModalClose,
  ModalDialog,
  Stack,
  Typography,
} from '@mui/joy';
import { useTonConnectUI } from '@tonconnect/ui-react';
import { useCallback, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useSetRecoilState } from 'recoil';
import { useBiometrySecureStorage, useLoadable } from '/src/hooks';
import { activeWalletSelector, walletsAtom, walletSettingModalAtom } from '/src/state';
import { WalletType } from '/src/types';

export const WalletSettingsModal = () => {
  const setOpen = useSetRecoilState(walletSettingModalAtom);
  const {
    errorMessage,
    isMounting,
    isAccessGranted,
    isAuthenticated,
    authenticating,
    authenticateStorage,
    removeRecord,
  } = useBiometrySecureStorage();
  const { t } = useTranslation();
  const setMyWallets = useSetRecoilState(walletsAtom);
  const [walletName, setWalletName] = useState('');
  const wallet = useLoadable(activeWalletSelector);
  const [tonconnectUi] = useTonConnectUI();
  const handleSave = useCallback(() => {
    setMyWallets((v) => [...v.map((m) => ({ ...m, name: walletName.substring(0, 24) }))]);
    setOpen(false);
  }, [setMyWallets, setOpen, walletName]);
  const removeWallet = useCallback(
    (address: string) =>
      setMyWallets(
        (v) =>
          [
            ...v.filter((f) => f.address != address), // filter wallet
          ].map((m, i) => (i == 0 ? { ...m, active: true } : m)), // activate first
      ),
    [setMyWallets],
  );
  const handleDeleteOrDisconnect = useCallback(async () => {
    if (!wallet) return;
    if (wallet.wallet == WalletType.tcsdk) {
      if (tonconnectUi.connected) {
        try {
          await tonconnectUi.disconnect();
          removeWallet(wallet.address);
          setOpen(false);
        } catch (err) {
          console.log('Error on tonconnectUi.disconnect', err);
        }
      }
    } else {
      if (errorMessage || !isAccessGranted) {
        return;
      }
      const response = await removeRecord(wallet.address);
      if (response) {
        removeWallet(wallet.address);
        setOpen(false);
      }
    }
  }, [wallet, tonconnectUi, setMyWallets, setOpen, errorMessage, isAccessGranted, removeRecord]);

  useEffect(() => {
    setWalletName(wallet?.name || '');
  }, [wallet]);

  return (
    <Modal open onClose={() => setOpen(false)}>
      <ModalDialog>
        <ModalClose />
        <Typography level="h3">{t('wallets.wallet-settings')}</Typography>
        <Typography level="body-md">{t('wallets.wallet-settings-description')}</Typography>
        <Divider />
        <form
          id="wallet-settings-form"
          name="wallet-settings-form"
          onSubmit={(e) => {
            e.preventDefault();
            handleSave();
          }}
        >
          <FormControl>
            <FormLabel>{t('wallets.wallet-name-label')}</FormLabel>
            <Input
              autoFocus
              required
              value={walletName}
              onChange={(e) => setWalletName(e.currentTarget.value)}
              type="text"
            />
          </FormControl>
        </form>
        {wallet?.wallet != WalletType.tcsdk && errorMessage && (
          <Alert color="danger" variant="soft">
            {errorMessage}
          </Alert>
        )}
        <DialogActions sx={{ justifyContent: 'space-between' }}>
          <Stack direction="row">
            <Button variant="plain" color="neutral" onClick={() => setOpen(false)}>
              Back
            </Button>
            <Button
              disabled={walletName.trim().length == 0}
              variant="solid"
              color="primary"
              type="submit"
              form="wallet-settings-form"
            >
              Save
            </Button>
          </Stack>
          <Button
            variant="outlined"
            color="danger"
            disabled={wallet?.wallet == WalletType.bip39 && !isAccessGranted}
            loading={wallet?.wallet == WalletType.bip39 && (authenticating || isMounting)}
            onClick={() => {
              if (!wallet) return;
              if (wallet?.wallet == WalletType.bip39 && !isAuthenticated && isAccessGranted)
                authenticateStorage();
              else {
                window.confirm(
                  t(
                    `Are you sure want to delete ${wallet?.wallet == WalletType.tcsdk ? 'disconnect' : 'delete'} wallet`,
                  ),
                ) && handleDeleteOrDisconnect();
              }
            }}
          >
            {t(
              wallet?.wallet == WalletType.tcsdk
                ? 'Disconnect wallet'
                : !isAuthenticated
                  ? 'Authenticate to delete'
                  : 'Delete wallet',
            )}
          </Button>
        </DialogActions>
      </ModalDialog>
    </Modal>
  );
};
