import { Address, toNano } from '@ton/core';
import { useEffect, useState } from 'react';
import { useParams } from 'react-router';
import { useResetRecoilState, useSetRecoilState } from 'recoil';
import { DEFAULT_DECIMAL_PLACES } from '../constants';
import { Jetton, JettonWallet } from '../contracts';
import { WalletEventManager, refreshDelayAtom, tonClientSelector } from '../state';
import { JettonWalletItem, RouteParams, WalletEventType } from '../types';
import { toUnits } from '../units';
import { delay, getAddress, waitForSeqno } from '../utils';
import { useLoadable } from './useLoadable';
import { useTonConnect } from './useTonConnect';

export function useProvideRewardPool(jetton?: JettonWalletItem) {
  const { address, smctype } = useParams<RouteParams>();
  const setRefreshDelay = useSetRecoilState(refreshDelayAtom);
  const resetRefreshDelay = useResetRecoilState(refreshDelayAtom);
  const [amount, setAmount] = useState('');
  const { sender, wallet } = useTonConnect();
  const [sendingTx, setSendingTx] = useState(false);
  const [closeForm, setCloseForm] = useState(false);
  const client = useLoadable(tonClientSelector);

  useEffect(() => {
    if (address) setAmount('');
  }, [address]);

  return {
    amount,
    setAmount,
    sendingTx,
    closeForm,
    sendProvideRewardPoolAction: async () => {
      if (!smctype || !client || !wallet || !address || !jetton || !jetton.jetton) {
        return;
      }
      const stakingMinterAddress = getAddress(address);
      const userPrimaryWalletAddress = getAddress(jetton.jetton);
      if (!userPrimaryWalletAddress || !stakingMinterAddress) {
        return;
      }
      const decimals = DEFAULT_DECIMAL_PLACES;
      const jettonAmount = toUnits(amount, decimals);

      setRefreshDelay(null);
      setSendingTx(true);

      const waiter = await waitForSeqno(client, Address.parse(wallet));
      const forwardTonAmount = toNano(0.06); // 0.056 is eligible but we set little bit more
      let senderFail = false;
      try {
        await sender?.send({
          to: userPrimaryWalletAddress,
          value: forwardTonAmount + toNano(0.06),
          body: JettonWallet.transferMessage(
            jettonAmount,
            stakingMinterAddress,
            sender.address!,
            null,
            forwardTonAmount,
            Jetton.provideRewardPoolMessage(),
          ),
        });
      } catch (error) {
        senderFail = true;
      }

      if (senderFail) {
        resetRefreshDelay();
        setSendingTx(false);
        return;
      }

      try {
        await waiter();
        await delay(10 * 1000);
      } catch (error) {}

      resetRefreshDelay();
      setSendingTx(false);
      setCloseForm(true);
      setAmount('');
      delay(1e4).finally(() =>
        WalletEventManager.publish(WalletEventType.RefetchAssets, { address, smcType: smctype }),
      );
    },
  };
}
