import throttle from 'lodash.throttle';
import { useEffect, useMemo } from 'react';
import { useParams } from 'react-router';
import { useRecoilValueLoadable } from 'recoil';
import { DEFAULT_DECIMAL_PLACES } from '../constants';
import { WalletEventManager, assetsSelector } from '../state';
import { RouteParams, WalletEventType } from '../types';
import { fromUnits } from '../units';
import { useActiveWallet } from './useActiveWallet';
import { useInterval } from './useInterval';
import { useJettonWallet } from './useJettonWallet';

const throttledRefetchAssets = throttle(
  (address: string) => {
    WalletEventManager.publish(WalletEventType.RefetchAssets, {
      address,
      smcType: 'staking',
    });
  },
  5e3,
  {
    trailing: true,
    leading: true,
  },
);

export function useStakingWallet() {
  const { address: minter } = useParams<RouteParams>();
  const { wallet } = useActiveWallet();
  const staking = useRecoilValueLoadable(assetsSelector(minter));
  const jetton = useJettonWallet({
    smc: 'staking',
    minter,
    wallet: wallet?.address,
    balanceTtl: 1e5,
  });
  const friendlyBalance = useMemo(
    () =>
      jetton.state === 'hasValue' && jetton.data
        ? Number(fromUnits(jetton.data.balance.value || 0n, DEFAULT_DECIMAL_PLACES))
        : 0,
    [jetton],
  );
  const showSkeleton = useMemo(() => !jetton && staking.state === 'loading', [jetton, staking]);

  useEffect(() => {
    if (minter) {
      throttledRefetchAssets(minter);
    }
  }, [minter]);

  useInterval(
    () => {
      if (minter) {
        throttledRefetchAssets(minter);
      }
    },
    minter ? 3e4 : null,
  );

  return {
    wallet,
    jetton,
    staking: staking.state === 'hasValue' && staking.contents ? staking.contents : undefined,
    friendlyBalance,
    loading: staking.state === 'loading' || jetton.state === 'loading',
    showSkeleton,
  };
}
