import { Add, Fingerprint, ImportExport, Telegram } from '@mui/icons-material';
import {
  Divider,
  List,
  ListItem,
  ListItemButton,
  ListItemContent,
  ListItemDecorator,
  Modal,
  ModalClose,
  ModalDialog,
  Typography,
} from '@mui/joy';
import { useTonConnectModal, useTonWallet } from '@tonconnect/ui-react';
import { useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useRecoilState, useSetRecoilState } from 'recoil';
import { GenerateWalletModal } from './generate-wallet-modal';
import { ImportWalletModal } from './import-wallet-modal';
import { api } from '/src/constants';
import { addWalletModalAtom, walletsAtom } from '/src/state';
import { WalletType } from '/src/types';
import { isTmaMobileDevice } from '/src/utils';

export const AddWalletModal = () => {
  const setOpen = useSetRecoilState(addWalletModalAtom);
  const [openImportWallet, setOpenImportWallet] = useState(false);
  const [openGenerateWallet, setOpenGenerateWallet] = useState(false);
  const { t } = useTranslation();
  const { open: openTonConnectModal } = useTonConnectModal();
  const tonconnectWallet = useTonWallet();
  const [myWallets, setMyWallets] = useRecoilState(walletsAtom);
  // const { mounted, isAuthorized, biometryIsNotAvailable, authenticateWithBiometry } = useBiometry();
  const { mounted, isAuthorized, biometryIsNotAvailable, authenticateWithBiometry } = {
    mounted: true,
    isAuthorized: true,
    biometryIsNotAvailable: false,
    authenticateWithBiometry: () => {},
  };
  const maxWallets = useMemo(() => myWallets.length > 4, [myWallets]);
  const isMobileDevice = useMemo(() => isTmaMobileDevice(), []);
  const canAddMore = !maxWallets && isMobileDevice;

  /**
   * Add tonconnect wallet
   */
  useEffect(() => {
    if (!tonconnectWallet) return;
    const address = tonconnectWallet.account.address;
    if (myWallets.find((f) => f.address == address)) return;
    setMyWallets((v) => [
      ...v
        // deactivate other wallets
        .map((m) => ({ ...m, active: false })),
      // push fresh active wallet
      {
        address,
        active: true,
        name: tonconnectWallet.device.appName,
        wallet: WalletType.tcsdk,
      },
    ]);
    setOpen(false);
  }, [tonconnectWallet]);

  return (
    <>
      <Modal open onClose={() => setOpen(false)}>
        <ModalDialog>
          <ModalClose />
          <Typography level="h3">{t('wallets.add-wallet')}</Typography>
          <Typography level="body-md">{t('wallets.create-new-wallet')}</Typography>
          <Divider />

          <List component="nav">
            {/* Biometry access */}
            {biometryIsNotAvailable ? (
              <ListItem>
                <ListItemDecorator>
                  <Fingerprint color="success" />
                </ListItemDecorator>
                <ListItemContent>
                  <Typography level="title-md">{t('wallets.biometry')}</Typography>
                  <Typography textColor="danger.500">
                    {t('wallets.biometry-not-supported')}
                  </Typography>
                </ListItemContent>
              </ListItem>
            ) : (
              !isAuthorized && (
                <ListItemButton
                  // disabled={!mounted}
                  onClick={() => authenticateWithBiometry()}
                >
                  <ListItemDecorator>
                    <Fingerprint color="success" />
                  </ListItemDecorator>
                  <ListItemContent>
                    <Typography level="title-md">{t('wallets.biometry')}</Typography>
                    <Typography>{t('wallets.biometry-authorize')}</Typography>
                  </ListItemContent>
                </ListItemButton>
              )
            )}

            {/* Create new */}
            {api.isWallet3 && !biometryIsNotAvailable && isAuthorized && canAddMore && (
              <ListItemButton onClick={() => setOpenGenerateWallet(true)}>
                <ListItemDecorator>
                  <Add />
                </ListItemDecorator>
                <ListItemContent>
                  <Typography level="title-md">{t('wallets.new-wallet')}</Typography>
                  <Typography>{t('wallets.create-wallet')}</Typography>
                </ListItemContent>
              </ListItemButton>
            )}
            {/* Import */}
            {api.isWallet3 && !biometryIsNotAvailable && isAuthorized && canAddMore && (
              <>
                {/* <ListDivider inset="startContent" /> */}
                <ListItemButton onClick={() => setOpenImportWallet(true)}>
                  <ListItemDecorator>
                    <ImportExport />
                  </ListItemDecorator>
                  <ListItemContent>
                    <Typography level="title-md">{t('wallets.existing-wallet')}</Typography>
                    <Typography>{t('wallets.import-wallet')}</Typography>
                  </ListItemContent>
                </ListItemButton>
              </>
            )}
            {/* Tonconnect */}
            {!tonconnectWallet && (
              <>
                {/* <ListDivider inset="startContent" /> */}
                <ListItemButton onClick={openTonConnectModal}>
                  <ListItemDecorator>
                    <Telegram sx={{ color: '#24A1DE' }} />
                  </ListItemDecorator>
                  <ListItemContent>
                    <Typography sx={{ color: '#24A1DE' }} level="title-md">
                      {t('wallets.tonconnect-wallet')}
                    </Typography>
                    <Typography>{t('wallets.tonconnect-description-wallet')}</Typography>
                  </ListItemContent>
                </ListItemButton>
              </>
            )}
          </List>
        </ModalDialog>
      </Modal>
      {openImportWallet && (
        <ImportWalletModal
          open={true}
          onClose={(v) => {
            setOpenImportWallet(v);
            setOpen(v);
          }}
          onBack={() => setOpenImportWallet(false)}
        />
      )}
      {openGenerateWallet && (
        <GenerateWalletModal
          open={true}
          onClose={(v) => {
            setOpenGenerateWallet(v);
            setOpen(v);
          }}
          onBack={() => setOpenGenerateWallet(false)}
        />
      )}
    </>
  );
};
