import { ContentCopy } from '@mui/icons-material';
import {
  Box,
  Button,
  Divider,
  Modal,
  ModalClose,
  ModalDialog,
  Snackbar,
  Typography,
} from '@mui/joy';
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useActiveWallet } from '../hooks';
import { qrcodegen, toSvgString } from '../libs/qrcodegen';
import { getAddress } from '../utils';

type Props = {
  open: boolean;
  setOpen: (v: boolean) => void;
};

const QRC = qrcodegen.QrCode;

export const ReceiveModal = ({ open, setOpen }: Props) => {
  const { t } = useTranslation();
  const { walletRestored } = useActiveWallet();
  const [svgStr, setSvgStr] = useState('');
  const [walletFriendly, setWalletFriendly] = useState('');
  const [openCopySnack, setOpenCopySnack] = useState(false);

  useEffect(() => {
    if (!walletRestored) return;
    const qr0 = QRC.encodeText(walletFriendly, QRC.Ecc.MEDIUM);
    setSvgStr(toSvgString(qr0, 2, '#fff', '#000'));
    const walletAddress = getAddress(walletRestored.address);
    setWalletFriendly(walletAddress?.toString() || '');
  }, [walletRestored]);

  return (
    <>
      <Modal open={open} onClose={() => setOpen(false)}>
        <ModalDialog>
          <ModalClose />
          <Typography level="h2">{t('receive.title')}</Typography>
          <Typography level="body-md">{t('receive.subtitle')}</Typography>
          <Divider />
          <Box
            display="flex"
            alignItems="center"
            alignSelf="center"
            flexDirection="column"
            gap={1}
            width={'100%'}
            p={1}
          >
            <img
              src={`data:image/svg+xml;utf8,${encodeURIComponent(svgStr)}`}
              style={{
                backgroundColor: 'white',
                borderRadius: 10,
              }}
            />
          </Box>
          <Typography level="body-sm" noWrap={true}>
            {walletFriendly}
          </Typography>
          <Button
            onClick={() => {
              setOpenCopySnack(true);
              navigator.clipboard.writeText(walletFriendly);
            }}
            endDecorator={<ContentCopy />}
          >
            {t('receive.copy')}
          </Button>
        </ModalDialog>
      </Modal>
      <Snackbar
        variant="soft"
        color="success"
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
        open={openCopySnack}
        onClose={() => setOpenCopySnack(false)}
        autoHideDuration={1000}
        startDecorator={<ContentCopy />}
        size="sm"
      >
        {t('receive.copied')}
      </Snackbar>
    </>
  );
};
