import { Close } from '@mui/icons-material';
import { IconButton, Snackbar, Stack, Typography } from '@mui/joy';
import { useEffect, useState } from 'react';
import { useRecoilState, useRecoilValue } from 'recoil';
import { lastSnackIdAtom, snacksAtom } from '../state';

export const Snacks = () => {
  const notifications = useRecoilValue(snacksAtom);
  const [open, setOpen] = useState(false);
  const [last, setLast] = useState<(typeof notifications)[number]>();
  const [lastId, setLastId] = useRecoilState(lastSnackIdAtom);

  useEffect(() => {
    setLast(notifications.at(-1));
  }, [notifications]);

  useEffect(() => {
    if (!last || last.id === lastId) return;
    setLastId(last.id);
    setOpen(true);
  }, [last]);

  return (
    <Snackbar
      sx={{ maxWidth: 320, px: 1, py: 0.5 }}
      anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      autoHideDuration={last?.autoHideDuration || 5e3}
      open={open}
      invertedColors
      variant={last?.variant || 'solid'}
      color={last?.color || 'neutral'}
      size="sm"
      endDecorator={
        <IconButton onClick={() => setOpen(false)}>
          <Close />
        </IconButton>
      }
      onClose={(event, reason) => {
        if (last?.color === 'danger' && reason === 'clickaway') {
          return;
        }
        setOpen(false);
      }}
      onUnmount={() => setLast(undefined)}
    >
      <Stack>
        {last?.title && (
          <Typography textColor="text.primary" level="body-md">
            {last.title}
          </Typography>
        )}
        {last?.body && (
          <Typography textColor="text.secondary" level="body-sm">
            {last.body}
          </Typography>
        )}
      </Stack>
    </Snackbar>
  );
};
