import { Address, Cell, Contract, ContractProvider, beginCell, toNano } from '@ton/core';
import { StakingParams, VestingData } from '../types';
import { Op } from './JettonConstants';

export class Jetton implements Contract {
  constructor(
    readonly address: Address,
    readonly init?: { code: Cell; data: Cell },
  ) {}

  async getWalletAddress(provider: ContractProvider, owner: Address) {
    const { stack } = await provider.get('get_wallet_address', [
      { type: 'slice', cell: beginCell().storeAddress(owner).endCell() },
    ]);

    return stack.readAddress();
  }

  async getJettonData(provider: ContractProvider) {
    const res = await provider.get('get_jetton_data', []);
    const totalSupply = res.stack.readBigNumber();
    const mintable = res.stack.readBoolean();
    const adminAddress = res.stack.readAddress();
    const content = res.stack.readCell();
    const walletCode = res.stack.readCell();

    return {
      totalSupply,
      mintable,
      adminAddress,
      content,
      walletCode,
    };
  }

  async getStakingData(provider: ContractProvider): Promise<StakingParams> {
    const res = await provider.get('get_staking_data', []);
    const lockup = res.stack.readNumber();
    const min_stake = res.stack.readBigNumber();
    const max_stake = res.stack.readBigNumber();
    const max_total = res.stack.readBigNumber();
    const reward_pool = res.stack.readBigNumber();
    const fixed_apy = res.stack.readBigNumber();
    return { lockup, min_stake, max_stake, max_total, reward_pool, fixed_apy };
  }

  async getVestingData(provider: ContractProvider): Promise<VestingData> {
    const result = await provider.get('get_vesting_data', []);
    return {
      totalDeposited: result.stack.readBigNumber(),
      startTime: result.stack.readNumber(),
      totalDuration: result.stack.readNumber(),
      unlockPeriod: result.stack.readNumber(),
      cliffDuration: result.stack.readNumber(),
    };
  }

  static topUpMessage() {
    return beginCell().storeUint(Op.top_up, 32).storeUint(0, 64).endCell();
  }

  static provideRewardPoolMessage() {
    return beginCell().storeUint(Op.provide_reward_pool, 32).endCell();
  }

  static provideStakeMessage(
    ton_amount: bigint = toNano(0.1),
    response_address: Address | null = null,
    forward_ton_amount: bigint = toNano(0.05),
  ) {
    return beginCell()
      .storeUint(Op.provide_stake, 32)
      .storeCoins(ton_amount)
      .storeAddress(response_address)
      .storeCoins(forward_ton_amount)
      .endCell();
  }

  static clawbackMessage(
    value: bigint = toNano(0.1),
    query_id: bigint | number = 0,
    responseAddress: Address | null = null,
  ) {
    return beginCell()
      .storeUint(Op.clawback, 32)
      .storeUint(query_id, 64)
      .storeCoins(value)
      .storeAddress(responseAddress)
      .endCell();
  }
}
