import { Check } from '@mui/icons-material';
import { Chip, Radio, RadioGroup } from '@mui/joy';
import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router';
import { STAKING_FIXED_APY_LIST } from '/src/constants';
import { RouteParams } from '/src/types';

const fixedApyKeys = Object.keys(STAKING_FIXED_APY_LIST);

export const FixedApyPicker = () => {
  const { address, smctype, root } = useParams<RouteParams>();
  const [apy, setApy] = useState<string>();
  const navigate = useNavigate();

  useEffect(() => {
    if (address) {
      setApy(fixedApyKeys.find((f) => STAKING_FIXED_APY_LIST[f] === address));
    }
  }, [address]);

  return (
    <RadioGroup name="fixed-apy" orientation="horizontal" sx={{ flexWrap: 'wrap', gap: 2 }}>
      {fixedApyKeys.map((name) => {
        const checked = apy === name;
        return (
          <Chip
            key={name}
            variant="soft"
            sx={{ px: { sm: 2 }, py: { sm: 0.75 } }}
            color={checked ? 'primary' : 'neutral'}
            startDecorator={checked && <Check sx={{ zIndex: 1, pointerEvents: 'none' }} />}
          >
            <Radio
              variant="outlined"
              color={checked ? 'primary' : 'neutral'}
              disableIcon
              overlay
              label={name}
              value={name}
              checked={checked}
              onChange={(event) => {
                if (event.target.checked) {
                  navigate(
                    `${root ? `/${root}/` : '/'}stats/${smctype || 'staking'}/${STAKING_FIXED_APY_LIST[name]}`,
                    {
                      replace: true,
                    },
                  );
                }
              }}
            />
          </Chip>
        );
      })}
    </RadioGroup>
  );
};
