import { AtomEffect, DefaultValue } from 'recoil';
import { BiometryTokenStorage } from './utils/biometry-token-storage';

type PersistenceOptions<T> = {
  defaultValue?: T | DefaultValue;
  // key: string;
  isValid: (value: T | DefaultValue) => boolean;
};

export const tmaSecureStorageEffect =
  <T>({ defaultValue, isValid }: PersistenceOptions<T>): AtomEffect<T> =>
  ({ setSelf, onSet, trigger }) => {
    const storage = new BiometryTokenStorage<T>();

    if (trigger === 'get') {
      let value: DefaultValue | T = new DefaultValue();
      storage
        .get()
        .then((parsedValue) => {
          if (parsedValue && isValid(parsedValue)) {
            setSelf(parsedValue);
          } else if (defaultValue) {
            value = defaultValue;
          }
        })
        .catch((err) => {
          console.log(`BiometryTokenStorage: Can't JSON.parse value from`, err);
          // NOTE: do not remove it as it possible to store client important data
          // storage.remove();
        });
      setSelf(value);
    }

    onSet((value, _, isReset) => {
      if (isReset) {
        storage.remove();
      } else if (isValid(value)) {
        storage.set(value);
      } else {
        throw `BiometryTokenStorage: Can't deal with invalid value`;
      }
    });
  };
