import { Address, beginCell, Cell, Contract, ContractProvider } from '@ton/core';
import { Op } from './JettonConstants';

export class JettonWallet implements Contract {
  constructor(
    readonly address: Address,
    readonly init?: { code: Cell; data: Cell },
  ) {}

  static transferMessage(
    jetton_amount: bigint,
    to: Address,
    responseAddress: Address | null,
    customPayload: Cell | null,
    forward_ton_amount: bigint,
    forwardPayload: Cell | null,
  ) {
    return beginCell()
      .storeUint(Op.transfer, 32)
      .storeUint(0, 64) // op, queryId
      .storeCoins(jetton_amount)
      .storeAddress(to)
      .storeAddress(responseAddress)
      .storeMaybeRef(customPayload)
      .storeCoins(forward_ton_amount)
      .storeMaybeRef(forwardPayload)
      .endCell();
  }

  static burnMessage(
    jetton_amount: bigint,
    responseAddress: Address | null,
    customPayload: Cell | null,
  ) {
    return beginCell()
      .storeUint(Op.burn, 32)
      .storeUint(0, 64) // op, queryId
      .storeCoins(jetton_amount)
      .storeAddress(responseAddress)
      .storeMaybeRef(customPayload)
      .endCell();
  }

  async getWalletData(provider: ContractProvider) {
    let { stack } = await provider.get('get_wallet_data', []);
    return {
      balance: stack.readBigNumber(),
      owner: stack.readAddress(),
      minter: stack.readAddress(),
      wallet_code: stack.readCell(),
    };
  }

  // staking
  async getStakeAt(provider: ContractProvider) {
    let res = await provider.get('get_stake_at', []);
    return res.stack.readNumber();
  }

  // vesting
  async getDeposit(provider: ContractProvider) {
    let res = await provider.get('get_deposit', []);
    return res.stack.readBigNumber();
  }
}
