import { atom, selectorFamily } from 'recoil';
import { getAddress } from '../utils';
import { localStorageEffect } from './effects';
import { instanceOfJettonWalletItemArray, JettonWalletItem } from '/src/types';

type Props = {
  minter?: string;
  wallet?: string;
};

export const jettonWalletsAtom = atom<JettonWalletItem[]>({
  key: 'jettonWalletsAtom',
  default: [],
  effects: [
    localStorageEffect<JettonWalletItem[]>({
      key: 'spintria-jetton-wallets',
      isValid: instanceOfJettonWalletItemArray,
      defaultValue: [],
    }),
  ],
});

export const jettonWalletsSelector = selectorFamily({
  key: 'jettonWalletsSelector',
  get:
    ({ minter, wallet }: Props) =>
    async ({ get }) =>
      minter && wallet
        ? get(jettonWalletsAtom)?.find((f) => {
            const minterA = getAddress(minter);
            if (!minterA) return;
            const walletA = getAddress(wallet);
            if (!walletA) return;
            return getAddress(f.minter)?.equals(minterA) && getAddress(f.wallet)?.equals(walletA);
          })
        : undefined,
});
