import { InfoOutlined } from '@mui/icons-material';
import {
  Box,
  Button,
  Card,
  CardContent,
  Divider,
  LinearProgress,
  Skeleton,
  Stack,
  Tooltip,
  Typography,
} from '@mui/joy';
import { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { FixedApyPicker } from './fixed-apy-picker';
import { ModalEarnForm } from './modal-earn-form';
import { ModalStakeForm } from './modal-stake-form';
import { DEFAULT_DECIMAL_PLACES, NOW } from '/src/constants';
import { useStakingWallet } from '/src/hooks';
import { spDayjs } from '/src/libs';
import { fromUnits } from '/src/units';
import { friendlyAmount } from '/src/utils';

export const FixedApyCard = () => {
  const { t } = useTranslation();
  const { jetton, staking, wallet, showSkeleton } = useStakingWallet();
  const [openStakeForm, setOpenStakeForm] = useState(false);
  const [openEarnForm, setOpenEarnForm] = useState(false);
  const [openApyTooltip, setOpenApyTooltip] = useState(false);
  const [openTvlTooltip, setOpenTvlTooltip] = useState(false);
  const tickerComponent = (
    <Typography textColor="neutral.400" fontSize="67.5%">
      {staking?.value.content?.symbol}
    </Typography>
  );

  const totalValueLockedProgress = useMemo(() => {
    if (!staking || !staking.staking) return 0;
    const totalSupply = Number(staking.value.totalSupply || 0n);
    const maxTotal = Number(staking.staking.max_total || 0n);

    return Math.ceil(totalSupply / (maxTotal / 100));
  }, [jetton]);

  const estEarning = useMemo(() => {
    if (!jetton.data?.balance || !staking?.staking || !jetton.data.balance.stakeAt) return;
    const decimals = DEFAULT_DECIMAL_PLACES;
    const day = 86400n;
    const diff = BigInt(NOW() - jetton.data.balance.stakeAt);
    const lockupTs = day * BigInt(staking.staking.lockup);
    // const timePassed = lockupTs > diff ? 0n : diff;
    const timePassed = diff;

    return {
      lockupNotPassed: lockupTs > diff,
      balance: jetton.data.balance.value,
      value: fromUnits(
        ((jetton.data.balance.value * staking.staking.fixed_apy) / 100n / (365n * day)) *
          timePassed,
        decimals,
      ),
      stakeAt: jetton.data.balance.stakeAt,
      unlockedAt: Number(lockupTs - diff),
    };
  }, [jetton]);

  return (
    <>
      <Card variant="plain" sx={{ width: '100%' }}>
        <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
          <Typography
            level="title-lg"
            mb={2}
            slotProps={{
              root: {
                onClick: () => setOpenApyTooltip(!openApyTooltip),
                onPointerEnter: () => setOpenApyTooltip(!openApyTooltip),
                onPointerLeave: () => setOpenApyTooltip(!openApyTooltip),
              },
            }}
          >
            {t('staking.card.title')}{' '}
            <Tooltip
              title={t('staking.form.apy-info')}
              variant="solid"
              open={openApyTooltip}
              placement="top"
            >
              <Typography
                endDecorator={<InfoOutlined color="secondary" sx={{ width: 18, height: 18 }} />}
              >
                {t('staking.form.apy')}
              </Typography>
            </Tooltip>
          </Typography>
          <FixedApyPicker />
        </CardContent>
        <Divider sx={{ my: 2 }} />
        <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
          <Typography level="title-lg" mb={2}>
            {t('staking.card.params')}
          </Typography>
          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
            <Typography textColor="text.tertiary">{t('staking.form.staking-lockup')}</Typography>
            <Typography textColor="text.tertiary" sx={{ position: 'relative', overflow: 'hidden' }}>
              <Skeleton loading={showSkeleton}>
                {staking?.staking?.lockup.toLocaleString() || '00'}
              </Skeleton>
            </Typography>
          </Stack>
          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
            <Typography textColor="text.tertiary">{t('staking.form.min-stake')}</Typography>
            <Typography textColor="text.tertiary" sx={{ position: 'relative', overflow: 'hidden' }}>
              <Skeleton loading={showSkeleton}>
                {staking?.staking?.min_stake
                  ? friendlyAmount(staking?.staking?.min_stake)
                  : '0,000'}
              </Skeleton>
            </Typography>
          </Stack>
          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
            <Typography textColor="text.tertiary">{t('staking.form.max-stake')}</Typography>
            <Typography textColor="text.tertiary" sx={{ position: 'relative', overflow: 'hidden' }}>
              <Skeleton loading={showSkeleton}>
                {staking?.staking?.max_stake
                  ? friendlyAmount(staking?.staking?.max_stake)
                  : '00,000,000'}
              </Skeleton>
            </Typography>
          </Stack>
          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
            <Typography textColor="text.tertiary">{t('staking.form.max-total')}</Typography>
            <Typography textColor="text.tertiary" sx={{ position: 'relative', overflow: 'hidden' }}>
              <Skeleton loading={showSkeleton}>
                {staking?.staking?.max_total
                  ? friendlyAmount(staking?.staking?.max_total)
                  : '00,000,000'}
              </Skeleton>
            </Typography>
          </Stack>
          <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1}>
            <Typography
              endDecorator={
                <Tooltip
                  open={openTvlTooltip}
                  title={
                    <Box
                      sx={{
                        display: 'flex',
                        flexDirection: 'column',
                        maxWidth: 256,
                        justifyContent: 'center',
                        // p: 1,
                      }}
                    >
                      {t('staking.card.tvl-info')}
                    </Box>
                  }
                  variant="solid"
                >
                  <InfoOutlined color="secondary" sx={{ width: 18, height: 18 }} />
                </Tooltip>
              }
              textColor="text.tertiary"
              slotProps={{
                root: {
                  onClick: () => setOpenTvlTooltip(!openTvlTooltip),
                  onPointerEnter: () => setOpenTvlTooltip(!openTvlTooltip),
                  onPointerLeave: () => setOpenTvlTooltip(!openTvlTooltip),
                },
              }}
            >
              {t('staking.card.tvl')}
            </Typography>
            <Typography textColor="text.tertiary" sx={{ position: 'relative', overflow: 'hidden' }}>
              <Skeleton loading={showSkeleton}>
                {staking?.value.totalSupply
                  ? friendlyAmount(staking?.value.totalSupply)
                  : '00,000,000'}
              </Skeleton>
            </Typography>
          </Stack>
          <LinearProgress determinate value={totalValueLockedProgress} sx={{ my: 2 }} />
        </CardContent>
        <Divider sx={{ my: 2 }} />
        <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
          <Typography level="inherit">{t('staking.card.you-deposited')}</Typography>
          <Typography
            fontSize="xl4"
            fontWeight="xl"
            mt={1}
            sx={{ position: 'relative', overflow: 'hidden' }}
          >
            <Skeleton loading={showSkeleton}>
              {jetton.data?.balance.value ? friendlyAmount(jetton.data?.balance.value) : '0'}{' '}
              {tickerComponent}
            </Skeleton>
          </Typography>
          {estEarning?.balance && estEarning?.balance > 0n && estEarning?.stakeAt ? (
            <Typography level="inherit" sx={{ position: 'relative', overflow: 'hidden' }}>
              {t('staking.card.stake-at')}:{' '}
              {new Date(estEarning.stakeAt * 1e3).toLocaleDateString()}
            </Typography>
          ) : (
            ''
          )}
          <Button
            disabled={!jetton || !staking?.staking}
            variant="soft"
            size="lg"
            fullWidth
            sx={{ borderRadius: 6, my: 2, py: 2, mb: 1 }}
            onClick={() => setOpenStakeForm(true)}
          >
            {t('staking.card.button-stake')}
          </Button>
        </CardContent>
        <Divider sx={{ my: 2 }} />
        <CardContent sx={{ textAlign: { xs: 'center', md: 'left' } }}>
          <Typography level="body-lg">{t('staking.card.available-for-claim')}</Typography>
          <Typography
            fontSize="xl4"
            fontWeight="xl"
            mt={1}
            sx={{ position: 'relative', overflow: 'hidden' }}
          >
            <Skeleton loading={showSkeleton}>
              {jetton.data?.balance.value ? friendlyAmount(jetton.data?.balance.value) : '0'}{' '}
              {tickerComponent}
            </Skeleton>
          </Typography>
          <Typography level="inherit" sx={{ position: 'relative', overflow: 'hidden' }}>
            <Skeleton loading={showSkeleton}>
              {t('staking.card.you-have-earned')}: ~{' '}
              {estEarning
                ? `${estEarning.value.toLocaleString()} ${staking?.value?.content?.symbol}`
                : ''}
            </Skeleton>
          </Typography>
          <Typography level="inherit" sx={{ position: 'relative', overflow: 'hidden' }}>
            <Skeleton loading={showSkeleton}>
              {estEarning?.balance && estEarning?.balance > 0n && estEarning?.lockupNotPassed ? (
                <Typography
                  level="inherit"
                  color={estEarning.lockupNotPassed ? 'warning' : 'success'}
                  sx={{ position: 'relative', overflow: 'hidden' }}
                >
                  {t('staking.card.lockup-not-passed')}, {t('staking.card.unlocked-at')}:{' '}
                  {spDayjs.duration(estEarning.unlockedAt, 'seconds').humanize(true)}
                </Typography>
              ) : (
                ''
              )}
            </Skeleton>
          </Typography>
          <Button
            disabled={!wallet || !jetton.data?.balance.value}
            variant="soft"
            size="lg"
            fullWidth
            sx={{ borderRadius: 6, py: 2, mt: 1 }}
            onClick={() => setOpenEarnForm(true)}
          >
            {t('staking.card.button-claim')}
          </Button>
        </CardContent>
      </Card>

      <ModalStakeForm
        open={openStakeForm}
        setOpen={setOpenStakeForm}
        staking={staking}
        loading={showSkeleton}
      />
      <ModalEarnForm
        open={openEarnForm}
        setOpen={setOpenEarnForm}
        staking={staking}
        stakingJetton={jetton.data}
        loading={showSkeleton}
      />
    </>
  );
};
