import { Api, TonApiClient } from '@ton-api/client';
import { ContractAdapter } from '@ton-api/ton-adapter';
import { RateLimiter } from './rate-limiter';

export const TONAPIKEY = 'AGCTK2AJ2VFDAYQAAAACGROUMVJQZJU4LUNYZV6FNHO5BDIJMKUCLQ77ESTKGDCEKX5HX6A';
const httpClient = new TonApiClient({ baseUrl: 'https://tonapi.io', apiKey: TONAPIKEY });

// Перехват метода request и оборачиваем его в планировщик лимитера
const originalRequest = httpClient.request.bind(httpClient);

// Инициализируем лимитер: 1 RPS для бесплатного тарифа, 3 попытки ретрая
const tonApiRateLimiter = new RateLimiter(1, 1250, 3);

httpClient.request = async function (args) {
  return tonApiRateLimiter.schedule(() => originalRequest(args));
};

export const tonApiClient = new Api(httpClient);
export const tonApiAdapter = new ContractAdapter(tonApiClient);
