import { useRecoilValueLoadable } from 'recoil';
import { WorkspaceNext } from '../workspace-next';
import { ActionsList } from './components/actions-list';
import { JettonsList } from './components/jettons-list';
import { SpintriaFaucet } from './components/spintria-faucet';
import { TotalBalance } from './components/total-balance';
import { TvlInfoNext } from './components/tvl-info-next';
import { api } from '/src/constants';
import { tmaLaunchParamsSelector } from '/src/state';

export const MainScreen = () => {
  const { state, contents } = useRecoilValueLoadable(tmaLaunchParamsSelector);

  return (
    <WorkspaceNext back={false}>
      <TotalBalance />
      <ActionsList />
      <TvlInfoNext />
      {api.isWallet3 &&
        state == 'hasValue' &&
        typeof contents?.tgWebAppData?.user?.id == 'number' && <SpintriaFaucet />}
      <JettonsList />
    </WorkspaceNext>
  );
};
