import { selectorFamily } from 'recoil';
import { vestingContractSelector } from './vesting-contract-selector';
import defaultRawJson from './vesting-jetton-meta-data.json';
import { getJettonMetadata, OFFCHAIN_URIS } from '/src/metadata';
import {
  instanceOfJettonData,
  instanceOfJettonMetadata,
  JettonData,
  JettonMetadata,
} from '/src/types';

export type JettonDataSelectorProps = {
  address?: string;
};

export const vestingJettonDataSelector = selectorFamily({
  key: 'vestingJettonDataSelector',
  get:
    ({ address }: JettonDataSelectorProps) =>
    async ({ get }) => {
      const minterContract = get(vestingContractSelector(address));
      let data: JettonData | undefined;
      try {
        data = await minterContract?.getJettonData();
      } catch (err) {}
      if (!data) {
        throw 'jetton-data-undefined';
      }
      if (minterContract && !instanceOfJettonData(data)) {
        throw 'corrupted-jetton-data';
      }
      // // let content = await getJettonMetadata(data.content);

      // // NOTE: shitty CORS
      // // if (content?.uri) {
      // //   const response = await fetch(content?.uri, {
      // //     method: 'GET',
      // //     headers: { 'Content-Type': 'application/json' },
      // //   });
      // //   const rawJson = response.json();
      // //   if (instanceOfJettonMetadata(rawJson)) content = rawJson;
      // // }
      // if (content?.uri && instanceOfJettonMetadata(rawJson)) {
      //   content = rawJson;
      // }
      let content: JettonMetadata | undefined;
      if (data) {
        content = await getJettonMetadata(data.content);
      }

      // NOTE: shitty CORS
      if (content?.uri) {
        let uriToFetch = content.uri;
        const foundedUri = OFFCHAIN_URIS.find((f) => content?.uri?.indexOf(f) !== -1);
        if (import.meta.env.DEV && foundedUri) {
          uriToFetch = foundedUri;
        }
        try {
          const response = await fetch(uriToFetch, {
            method: 'GET',
            headers: { 'Content-Type': 'application/json' },
          });
          const rawJson = await response.json();
          if (instanceOfJettonMetadata(rawJson)) {
            content = rawJson;
          }
        } catch (err) {
          if (instanceOfJettonMetadata(defaultRawJson)) {
            content = defaultRawJson;
          }
        }
      }
      return { ...data, content };
    },
});
