import { atom, DefaultValue, selector, selectorFamily } from 'recoil';
import { DIRECT_VESTING_CONTRACTS, NOW } from '../constants';
import { DirectVestingContract, DirectVestingData } from '../contracts';
import { getAddress } from '../utils';
import { tonCenterClientSelector, tonClientSelector } from './ton';
import { activeWalletSelector } from './wallets';

// Интерфейс для типизации данных контракта
interface VestingDataState {
  address: string;
  data: DirectVestingData;
  locked: bigint;
}

export const vestingContractAddressSelector = selector({
  key: 'vestingContractAddressSelector',
  get: async ({ get }) => {
    const wallet = get(activeWalletSelector);
    if (!wallet) return;
    if (!DIRECT_VESTING_CONTRACTS[wallet.address]) return;
    return getAddress(DIRECT_VESTING_CONTRACTS[wallet.address]);
  },
});

// 2. АТОМ вместо селектора. Сюда данные запишутся ОДИН раз.
export const directVestingAtom = atom<VestingDataState | null | undefined>({
  key: 'directVestingAtom',
  default: undefined, // undefined - еще не загружалось, null - нет контракта
});

export const directVestingSelector = selector({
  key: 'directVestingSelector',
  get: async ({ get }) => {
    // 'register' as a resetable dependency
    get(directVestingVersion);
    const vesingAddr = get(vestingContractAddressSelector);
    if (!vesingAddr) return;
    const client = get(tonCenterClientSelector);
    const contract = client.open(new DirectVestingContract(vesingAddr));
    try {
      const data = await contract.getVestingData();
      const locked = await contract.getLockedAmount(NOW());
      if (!data || !locked) return;
      return { address: vesingAddr.toRawString(), data, locked };
    } catch (error) {
      console.log('DirectVestingContract fetch data error', error);
      throw error;
    }
  },
  set: ({ set }, value) => {
    if (value instanceof DefaultValue) {
      set(directVestingVersion, (v) => v + 1);
    }
  },
});

export const directVestingVersion = atom({
  key: 'directVestingVersion',
  default: 0,
});

export const directVestingByAddress = selectorFamily({
  key: 'directVestingByAddress',
  get:
    (address?: string) =>
    async ({ get }) => {
      if (!address) return;
      if (!DIRECT_VESTING_CONTRACTS[address]) return;
      const vesingAddr = getAddress(DIRECT_VESTING_CONTRACTS[address]);
      if (!vesingAddr) return;
      const client = get(tonClientSelector);
      const contract = client.open(new DirectVestingContract(vesingAddr));
      try {
        const data = await contract.getVestingData();
        const locked = await contract.getLockedAmount(NOW());
        if (!data || !locked) return;
        return { address: vesingAddr.toRawString(), data, locked };
      } catch (error) {
        console.info('DirectVestingByAddress fetch data error', error);
        throw error;
      }
    },
});
