import { atom } from 'recoil';
import { STORAGE_ZERO_JETTONS_KEY } from '../constants';
import { localStorageEffect } from './effects';

export const zeroJettonsAtom = atom({
  key: 'zeroJettonsAtom',
  default: false,
  effects: [
    localStorageEffect<boolean>({
      key: STORAGE_ZERO_JETTONS_KEY,
      isValid: (v) => typeof v === 'boolean',
      defaultValue: false,
    }),
  ],
});
