import { InfoOutlined } from '@mui/icons-material';
import {
  Box,
  Card,
  CardContent,
  CircularProgress,
  IconButton,
  Skeleton,
  Stack,
  SvgIcon,
  Tooltip,
  Typography,
} from '@mui/joy';
import { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useRecoilValue, useRecoilValueLoadable } from 'recoil';
import { MAINNET_SPINTRIA_MASTER_ADDRESS } from '/src/constants';
import { currencyAtom, ratesSelector, tvlSelector } from '/src/state';
import { appCurrencies, isTvlResponse } from '/src/types';
import { fromUnits } from '/src/units';

export const TvlInfoNext = () => {
  const { t } = useTranslation();
  const [openTvlHint, setOpenTvlHint] = useState(false);
  const rates = useRecoilValueLoadable(ratesSelector({ address: MAINNET_SPINTRIA_MASTER_ADDRESS }));
  const currency = useRecoilValue(currencyAtom);
  const tvl = useRecoilValueLoadable(tvlSelector);
  const totalTvl = useMemo(() => {
    if (tvl.state == 'loading') return;
    if (
      rates.state !== 'hasValue' ||
      !rates.contents ||
      !rates.contents.prices ||
      !rates.contents.prices[currency]
    )
      return;
    const tvlValue = isTvlResponse(tvl.contents) ? tvl.contents.value : 0;
    const rate = rates.contents.prices[currency];
    return Number(fromUnits(tvlValue.toString(), 8)) * rate;
  }, [tvl, rates, currency]);

  return (
    <Card variant="soft" color="primary" invertedColors>
      <CardContent orientation="horizontal">
        <CircularProgress size="lg" determinate value={20}>
          <SvgIcon>
            <svg
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
              strokeWidth={1.5}
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M2.25 18L9 11.25l4.306 4.307a11.95 11.95 0 015.814-5.519l2.74-1.22m0 0l-5.94-2.28m5.94 2.28l-2.28 5.941"
              />
            </svg>
          </SvgIcon>
        </CircularProgress>
        <CardContent>
          <Stack direction="row" width="100%" justifyContent="space-between">
            <Box>
              <Typography level="body-md">{t('tvl.title')}</Typography>
              <Typography
                level="h2"
                startDecorator={
                  <Typography sx={{ color: '#8888', marginInlineEnd: -0.75 }}>
                    {appCurrencies[currency].symbol}
                  </Typography>
                }
              >
                {totalTvl != undefined ? (
                  totalTvl == 0 ? (
                    '...'
                  ) : (
                    totalTvl.toLocaleString(undefined, {
                      notation: 'compact',
                      maximumFractionDigits: 2,
                    })
                  )
                ) : (
                  <Skeleton variant="rectangular" animation={false} height=".875em">
                    000
                  </Skeleton>
                )}
              </Typography>
            </Box>

            <Tooltip
              open={openTvlHint}
              variant="outlined"
              arrow
              title={
                <Box
                  sx={{
                    display: 'flex',
                    flexDirection: 'column',
                    maxWidth: 600,
                    justifyContent: 'center',
                    p: 0,
                    margin: 1,
                  }}
                >
                  <Typography sx={{ fontSize: 'md', fontWeight: 'lg' }}>
                    {t('tvl.hint-title')}
                  </Typography>
                  <Typography sx={{ fontSize: 'sm' }}>{t('tvl.hint-body')}</Typography>
                </Box>
              }
            >
              <IconButton onClick={() => setOpenTvlHint(!openTvlHint)}>
                <InfoOutlined />
              </IconButton>
            </Tooltip>
          </Stack>
        </CardContent>
      </CardContent>
    </Card>
  );
};
