import {
  Alert,
  Button,
  ButtonGroup,
  DialogActions,
  Divider,
  Input,
  Modal,
  ModalClose,
  ModalDialog,
  modalDialogClasses,
  Stack,
  Typography,
} from '@mui/joy';
import { useTranslation } from 'react-i18next';
import { useWalletModal } from './useWalletModal';

type Props = {
  open: boolean;
  onClose: (v: boolean) => void;
  onBack: () => void;
};

export const ImportWalletModal = ({ open, onClose, onBack }: Props) => {
  const { t } = useTranslation();
  const {
    phrase,
    phraseCount,
    phraseChange,
    phraseValid,
    generatePhrase,
    generating,
    setPhraseCount,
    finishAddOrImport,
    walletName,
    retryMessage,
    isMounting,
    isAuthenticated,
    authenticating,
    isAccessGranted,
    authenticateStorage,
  } = useWalletModal('import');

  return (
    <Modal open={open} onClose={() => onBack()}>
      <ModalDialog
        sx={{
          [`&.${modalDialogClasses.root}`]: {
            // maxWidth: '100vw',
            // maxHeight: 'calc(100% - var(--Card-padding))',
          },
        }}
      >
        <ModalClose />
        <Typography level="h3">{t('wallets.import.title')}</Typography>
        <Typography level="body-md">{t('wallets.import.description')}</Typography>
        <Divider />
        <ButtonGroup>
          <Button disabled={phraseCount == 24} onClick={() => setPhraseCount(24)}>
            {t('wallets.import.words24')}
          </Button>
          <Button disabled={phraseCount == 12} onClick={() => setPhraseCount(12)}>
            {t('wallets.import.words12')}
          </Button>
          {import.meta.env.DEV && (
            <Button
              color="danger"
              variant="solid"
              loading={generating}
              onClick={() => generatePhrase()}
            >
              GENERATE
            </Button>
          )}
        </ButtonGroup>
        <Stack
          gap={1}
          overflow="scroll"
          sx={{
            mx: 'calc(-1 * var(--Card-padding))',
            mb: 'calc(-1 * var(--Card-padding))',
            px: 'var(--Card-padding)',
            pb: 'var(--Card-padding)',
          }}
        >
          <Stack spacing={1} direction="row" useFlexGap sx={{ flexWrap: 'wrap' }}>
            {phrase?.map((m, i) => (
              <Input
                key={`input-phrase-${i}`}
                sx={{ flexGrow: 1 }}
                startDecorator={`${i + 1}:`}
                value={m.word}
                error={!m.valid}
                onChange={(e) => phraseChange(i, e.target.value || '')}
              />
            ))}
          </Stack>
        </Stack>
        <form
          id="import-wallet-form"
          name="import-wallet-form"
          onSubmit={(e) => {
            e.preventDefault();
            finishAddOrImport(onClose);
          }}
        >
          <input
            id="username"
            value={walletName}
            type="text"
            name="username"
            autoComplete="username"
            style={{ display: 'none' }}
            onChange={() => {}}
          />
          <input
            id="new-phrase"
            type="password"
            name="new-phrase"
            value={phrase?.map((m) => m.word).join(',') || ''}
            autoComplete="new-password"
            style={{ display: 'none' }}
            onChange={() => {}}
          />
        </form>
        {retryMessage && (
          <Alert color="danger" variant="soft">
            {retryMessage}
          </Alert>
        )}
        <DialogActions>
          {isAuthenticated ? (
            <Button
              variant="solid"
              color="primary"
              type="submit"
              form="import-wallet-form"
              disabled={!phraseValid}
            >
              Continue
            </Button>
          ) : isAccessGranted ? (
            <Button
              loading={isMounting || authenticating}
              variant="solid"
              color="primary"
              onClick={() => authenticateStorage()}
            >
              {t('Authenticate')}
            </Button>
          ) : (
            <></>
          )}
          <Button variant="plain" color="neutral" onClick={() => onBack()}>
            Back
          </Button>
        </DialogActions>
      </ModalDialog>
    </Modal>
  );
};
