import { jsonReplacer, jsonReviver } from './json-utils';

export class StateStorage<T> {
  private key: string;

  constructor(key: string) {
    this.key = key;
  }

  public get(): T | null {
    try {
      const value = window.localStorage.getItem(this.key);
      if (!value) return null;
      return JSON.parse(value, jsonReviver) as T;
    } catch (error) {
      throw new Error('Failed to retrieve value from storage');
    }
  }

  public set(value: T): void {
    try {
      window.localStorage.setItem(this.key, JSON.stringify(value, jsonReplacer));
    } catch (error) {
      throw new Error('Failed to set value in storage');
    }
  }

  public remove(): void {
    try {
      window.localStorage.removeItem(this.key);
    } catch (error) {
      throw new Error('Failed to remove value from storage');
    }
  }
}
