import { atom, DefaultValue, selectorFamily } from 'recoil';
import {
  MAINNET_SPINTRIA_MASTER_ADDRESS,
  RATES_REFRESH_DELAY_INTERVAL,
  STORAGE_RATES_KEY,
  TON_TICKER,
} from '../constants';
import { StateStorage } from './effects/utils/state-storage';
import { tonApiClient } from './ton';
import { appCurrencies, instanceOfJettonRates, TonApiRates } from '/src/types';

export const ratesAtom = atom<TonApiRates>({
  key: 'ratesAtom',
  default: { timestamp: NaN, rates: {} },
  effects: [
    ({ setSelf, onSet, trigger }) => {
      const storage = new StateStorage<TonApiRates>(STORAGE_RATES_KEY);
      const refetchAsync = async () => {
        const data = await tonApiClient.rates.getRates({
          tokens: [[TON_TICKER, MAINNET_SPINTRIA_MASTER_ADDRESS].join(',')],
          currencies: [Object.keys(appCurrencies).join(',')],
        });
        const tonApiRates: TonApiRates = {
          rates: data.rates,
          timestamp: Date.now(),
        };
        storage.set(tonApiRates);
        setSelf(tonApiRates);
      };
      if (trigger === 'get') {
        let value: DefaultValue | TonApiRates = new DefaultValue();
        try {
          const parsedValue = storage.get();
          if (instanceOfJettonRates(parsedValue)) {
            value = parsedValue;
            // refetch if stale (30 min)
            if (Date.now() > parsedValue.timestamp + 6e4 * 30) {
              refetchAsync();
            }
          } else {
            // refetch if not set
            refetchAsync();
          }
        } catch (err) {
          console.info(`Can't JSON.parse value from`, STORAGE_RATES_KEY);
          storage.remove();
        }
        setSelf(value);
      }
      onSet((value, _, isReset) => {
        if (isReset || !instanceOfJettonRates(value)) {
          storage.remove();
        } else {
          storage.set(value);
        }
      });
      const refetchInterval = window.setInterval(refetchAsync, RATES_REFRESH_DELAY_INTERVAL);
      return () => {
        typeof refetchInterval != 'undefined' && window.clearInterval(refetchInterval);
      };
    },
  ],
});

export const ratesSelector = selectorFamily({
  key: 'ratesSelector',
  get:
    ({ address }: { address?: string }) =>
    async ({ get }) =>
      address ? get(ratesAtom).rates[address] : undefined,
});
