import {
  Autocomplete,
  AutocompleteOption,
  FormControl,
  FormHelperText,
  FormLabel,
  ListItemContent,
  Stack,
  Typography,
} from '@mui/joy';
import { useTranslation } from 'react-i18next';
import { useNavigate, useParams } from 'react-router';
import { DIRECT_VESTING_CONTRACTS } from '/src/constants';
import { RouteParams } from '/src/types';
import { getAddress } from '/src/utils';

const friendlyAddrs = Object.entries(DIRECT_VESTING_CONTRACTS)
  .map(([owner, contract]) => [
    owner,
    contract,
    getAddress(owner)?.toString(),
    getAddress(contract)?.toString(),
  ])
  .map(([owner, contract, ownerF, contractF]) => ({
    owner,
    contract,
    ownerF,
    contractF,
  }));

export const DirectVestingPicker = () => {
  const navigate = useNavigate();
  const { address, smctype, root } = useParams<RouteParams>();
  const dvc = friendlyAddrs.find((f) => f.owner == address);
  const { t } = useTranslation();

  return (
    <FormControl>
      <FormLabel sx={{ px: 0 }}>{t('direct-vesting.pick-contract')}</FormLabel>
      <Autocomplete
        sx={{ py: 1 }}
        size="lg"
        options={friendlyAddrs}
        value={dvc}
        getOptionLabel={(option) => option.contractF || ''}
        isOptionEqualToValue={(o, v) => o.contractF == v.contractF}
        renderOption={(props, option) => (
          <AutocompleteOption {...props}>
            <ListItemContent sx={{ fontSize: 'sm' }}>
              {option.contractF}
              <Typography level="body-xs">Owner: {option.ownerF}</Typography>
            </ListItemContent>
          </AutocompleteOption>
        )}
        placeholder="..."
        onInputChange={(event, newInputValue) => {
          const founded = friendlyAddrs.find((f) => f.contractF == newInputValue);
          if (founded)
            navigate(
              `${root ? `/${root}/` : '/'}stats/${smctype || 'direct-vesting'}/${founded.owner}`,
              {
                replace: true,
              },
            );
        }}
      />
      {!address ? (
        <FormHelperText sx={{ px: 0, color: (t) => t.vars.palette.danger.plainColor }}>
          {t('staking.incorrect-contract')}
        </FormHelperText>
      ) : (
        <FormHelperText sx={{ px: 0, color: (t) => t.vars.palette.danger.plainColor }}>
          {t('staking.do-not-transfer')}
        </FormHelperText>
      )}
      {dvc && (
        <FormHelperText sx={{ px: 0, color: (t) => t.vars.palette.danger.plainColor }}>
          <Stack>
            <Typography>Onwer: {dvc.ownerF}</Typography>
            <Typography>Contract: {dvc.contractF}</Typography>
          </Stack>
        </FormHelperText>
      )}
    </FormControl>
  );
};
