import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  TELEGRAM_CLOUDSTORAGE_WELCOME_KEY,
  TELEGRAM_CLOUDSTORAGE_WELCOME_VALUE,
} from '../../constants';

import {
  Button,
  DialogActions,
  DialogTitle,
  Divider,
  Modal,
  ModalClose,
  ModalDialog,
} from '@mui/joy';
import { Step0Body, Step0Title, Step1Body, Step1Title, Step2Body, Step2Title } from './steps';

export const WelcomeDialog = () => {
  const [open, setOpen] = useState(false);
  useEffect(() => {
    const value = window.localStorage.getItem(TELEGRAM_CLOUDSTORAGE_WELCOME_KEY);
    setOpen(value !== TELEGRAM_CLOUDSTORAGE_WELCOME_VALUE);
  }, []);

  return open ? <WelcomeDialogInner open={open} setOpen={setOpen} /> : <></>;
};

export const WelcomeDialogInner = ({
  open,
  setOpen,
}: {
  open: boolean;
  setOpen: (b: boolean) => void;
}) => {
  const [currentStep, setCurrentStep] = useState(0);
  const closeWelcomeDialog = useCallback(() => {
    window.localStorage.setItem(
      TELEGRAM_CLOUDSTORAGE_WELCOME_KEY,
      TELEGRAM_CLOUDSTORAGE_WELCOME_VALUE,
    );
    setOpen(false);
  }, []);

  const titleComponent = useMemo(() => {
    switch (currentStep) {
      case 1: {
        return <Step1Title />;
      }
      case 2: {
        return <Step2Title />;
      }
      case 0:
      default: {
        return <Step0Title />;
      }
    }
  }, [currentStep]);

  const boyComponent = useMemo(() => {
    switch (currentStep) {
      case 1: {
        return <Step1Body />;
      }
      case 2: {
        return <Step2Body />;
      }
      case 0:
      default: {
        return <Step0Body />;
      }
    }
  }, [currentStep]);

  return (
    <Modal open={open} onClose={() => closeWelcomeDialog()}>
      <ModalDialog layout="fullscreen">
        <DialogTitle level="h2">
          <ModalClose />
          {titleComponent}
        </DialogTitle>
        {boyComponent}
        <Divider />
        <DialogActions>
          {currentStep >= 2 && (
            <Button fullWidth variant="solid" color="success" onClick={() => closeWelcomeDialog()}>
              Close
            </Button>
          )}
          {currentStep < 2 && (
            <Button
              fullWidth
              variant="solid"
              color="primary"
              onClick={() => setCurrentStep((v) => v + 1)}
            >
              Next
            </Button>
          )}
          <Button
            fullWidth
            disabled={currentStep === 0}
            variant="plain"
            color="neutral"
            onClick={() => setCurrentStep((v) => v - 1)}
          >
            Back
          </Button>
        </DialogActions>
      </ModalDialog>
    </Modal>
  );
};
