import { useEffect, useState } from 'react';
import { useParams } from 'react-router';
import { WorkspaceNext } from '../workspace-next';
import { StakingBody } from './components/staking/staking-body';
import { DirectVestingInfo } from './components/vesting/direct-vesting-info';
import { VestingJettonInfo } from './components/vesting/vesting-jetton-info';
import { DIRECT_VESTING_CONTRACTS } from '/src/constants';
import { RouteParams, SmcType } from '/src/types';
import { findAddressInArray, getSpintriaAccountsBySmcType } from '/src/utils';

export const JettonScreen = () => {
  const { address } = useParams<RouteParams>();
  const [smcType, setSmcType] = useState<SmcType>();

  useEffect(() => {
    if (!address) return;

    if (Object.values(DIRECT_VESTING_CONTRACTS).indexOf(address) !== -1) {
      setSmcType('direct-vesting');
    } else if (findAddressInArray(getSpintriaAccountsBySmcType('jetton'), address)) {
      setSmcType('jetton');
    } else if (findAddressInArray(getSpintriaAccountsBySmcType('staking'), address)) {
      setSmcType('staking');
    } else if (findAddressInArray(getSpintriaAccountsBySmcType('vesting'), address)) {
      setSmcType('vesting');
    }
  }, [address]);

  return smcType ? (
    <WorkspaceNext>
      {smcType === 'jetton' && <>jetton</>}
      {smcType === 'staking' && <StakingBody />}
      {smcType === 'vesting' && <VestingJettonInfo />}
      {smcType === 'direct-vesting' && <DirectVestingInfo />}
    </WorkspaceNext>
  ) : (
    <></>
  );
};
