import { biometry, isTMA } from '@telegram-apps/sdk-react';
import { mnemonicToWalletKey } from '@ton/crypto';
import { WalletContractV4 } from '@ton/ton';
import { useCallback, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { BiometryWallets } from '../state';

type BiometryWalletsMin = {
  v: BiometryWallets['version'];
  ms: BiometryWallets['mnemonics'];
};

const MNEMONIC_SEP = ',';
const defaultBioWallsValue: BiometryWallets = { version: 1, mnemonics: [] };

function isBiometryWallets(o: any): o is BiometryWallets {
  return (
    o &&
    'version' in o &&
    typeof o.version == 'number' &&
    'mnemonics' in o &&
    Array.isArray(o.mnemonics)
  );
}

function isBiometryWalletsMin(o: any): o is BiometryWalletsMin {
  return o && 'v' in o && typeof o.v == 'number' && 'ms' in o && Array.isArray(o.ms);
}

const packStorage = (value: BiometryWallets) =>
  JSON.stringify({ v: value.version, ms: value.mnemonics } as BiometryWalletsMin);

export function useBiometrySecureStorage() {
  const { t } = useTranslation();
  // const [secureStorage, setSecureStorage] = useRecoilState(secureStorageState);
  const [secureStorage, setSecureStorage] = useState<BiometryWallets>();
  const [isMounting, setMounting] = useState(false);
  const [mounted, setMounted] = useState(false);
  const [storageCorrupted, setStorageCorrupted] = useState(false);
  const [isAccessGranted, setAccessGranted] = useState(false);
  const [authenticating, setAuthenticating] = useState(false);
  const [isAuthenticated, setAuthenticated] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string>();
  const unpackStorage = useCallback(
    (rawValue?: string) => {
      try {
        if (!rawValue) return;
        const parsedValue = JSON.parse(rawValue);
        if (isBiometryWalletsMin(parsedValue)) {
          return {
            version: parsedValue.v,
            mnemonics: parsedValue.ms,
          } as BiometryWallets;
        }
      } catch (error) {
        setStorageCorrupted(true);
        // throw new Error('Failed to retrieve value from storage');
        // console.log('Failed to retrieve value from storage');
        // return defaultBioWallsValue;
      }
    },
    [setStorageCorrupted],
  );
  const requestAccessFlow = useCallback(async () => {
    if (!biometry.requestAccess.isAvailable()) {
      setErrorMessage('biometry request access is not available');
      return;
    }
    const access = await biometry.requestAccess();
    setAccessGranted(access);
    if (!access) {
      if (biometry.openSettings.isAvailable()) {
        biometry.openSettings();
      } else {
        setErrorMessage('biometry openSettings is not available');
        return;
      }
    }
  }, []);

  const authenticateStorage = useCallback(async () => {
    setAuthenticating(true);
    if (!biometry.authenticate.isAvailable()) {
      setErrorMessage('biometry authenticate is not available');
      return;
    }
    const response = await biometry.authenticate({
      reason: t('wallets.biometry-authenticate'),
    });
    setAuthenticated(response.status === 'authorized');
    if (response.status == 'authorized') {
      try {
        // previous token is empty
        if (!response.token) {
          setSecureStorage(defaultBioWallsValue);
        } else {
          const unpacked = unpackStorage(response.token);
          if (unpacked) {
            setSecureStorage(unpacked);
          }
        }
      } catch (error) {
        // TODO: snack error
        // corrupted wallet
      }
    }
    setAuthenticating(false);
  }, []);

  const addRecord = async (m: string[]) => {
    if (storageCorrupted || !secureStorage) return;
    if (secureStorage.mnemonics.length > 4) {
      setErrorMessage('not enough storage');
      return;
    }
    return updageStorage(
      packStorage({
        version: secureStorage.version,
        mnemonics: [...secureStorage.mnemonics, m.join(MNEMONIC_SEP)],
      }),
    );
  };

  const removeRecord = async (addressToRemove: string) => {
    if (storageCorrupted || !secureStorage || secureStorage.mnemonics.length == 0) {
      return;
    }
    let founded: (typeof secureStorage)['mnemonics'][number] | undefined;
    for await (const mnemonic of secureStorage.mnemonics) {
      const { publicKey } = await mnemonicToWalletKey(mnemonic.split(MNEMONIC_SEP));
      const walletContract = WalletContractV4.create({ publicKey, workchain: 0 });
      if (!walletContract) return;
      if (addressToRemove == walletContract.address.toRawString()) {
        founded = mnemonic;
        break;
      }
    }
    if (!founded) {
      console.log('It looks like there are no records in the repository, is storage corrupted?');
      return;
    }
    return updageStorage(
      packStorage({
        version: secureStorage.version,
        mnemonics: secureStorage.mnemonics.filter((f) => f != founded),
      }),
    );
  };

  const signTx = useCallback(
    async (address: string) => {
      if (secureStorage) return;
      console.log('sign here');
    },
    [secureStorage],
  );

  const updageStorage = useCallback(async (token: string) => {
    if (!biometry.updateToken.isAvailable()) {
      setErrorMessage('biometry authenticate is not available');
      return;
    }
    try {
      const response = await biometry.updateToken({ token });
      if (response == 'updated') {
        // clean current state
        setSecureStorage(undefined);
        return response;
      }
    } catch (err) {
      console.log('biometry updateToken error', err);
      setErrorMessage('biometry update failed');
    }
  }, []);

  /**
   * Effects
   */
  useEffect(() => {
    let controller: AbortController | undefined = new AbortController();
    if (!isTMA()) {
      setErrorMessage('biometry is not under TMA');
      return;
    }
    if (!biometry.isSupported()) {
      setErrorMessage('biometry is not supported');
      return;
    }
    if (!biometry.mount.isAvailable()) {
      setErrorMessage('biometry mount is not vailable');
      return;
    }
    if (biometry.isMounted()) {
      setMounted(true);
      return;
    }
    controller = new AbortController();
    (async () => {
      try {
        setMounting(true);
        await biometry.mount(controller.signal);
        setMounting(false);
        setMounted(biometry.isMounted());
      } catch (err) {
        if (biometry.mountError() == err) {
          console.log('biometry mount error', err);
        } else {
          console.log('unspecified biometry error', err);
        }
      }
    })();

    return () => controller?.abort();
  }, []);

  useEffect(() => {
    if (mounted && !isMounting) {
      requestAccessFlow();
    }
  }, [mounted, isMounting]);

  useEffect(() => {
    if (secureStorage) {
      setAccessGranted(true);
      setAuthenticated(true);
    }
  }, [secureStorage]);

  useEffect(() => {
    // console.log('secureStorage on change', secureStorage);
  }, [secureStorage]);

  return {
    storageCorrupted,
    errorMessage,
    isMounting,
    isAccessGranted,
    isAuthenticated,
    authenticating,
    authenticateStorage,
    signTx,
    addRecord,
    removeRecord,
  };
}
