export class RateLimiter {
  private queue: (() => void)[] = [];
  private tokens: number;
  private intervalId: number;

  constructor(
    private maxRps: number = 1,
    private refillIntervalMs: number = 1000,
    private maxRetries: number = 3, // Максимальное количество попыток
  ) {
    this.tokens = maxRps;
    this.intervalId = window.setInterval(() => this.refill(), refillIntervalMs);
  }

  private refill() {
    this.tokens = this.maxRps;
    while (this.tokens > 0 && this.queue.length > 0) {
      const resolve = this.queue.shift();
      if (resolve) {
        resolve();
        this.tokens--;
      }
    }
  }

  public async schedule<T>(fn: () => Promise<T>, attempt: number = 0): Promise<T> {
    return new Promise((resolve, reject) => {
      const execute = async () => {
        try {
          resolve(await fn());
        } catch (error: any) {
          // Проверяем, является ли ошибка ответом 429 от TonAPI
          const is429 = error?.status === 429 || error?.response?.status === 429;

          if (is429 && attempt < this.maxRetries) {
            // Вычисляем задержку: например, 1000мс, 2000мс, 4000мс...
            const delay = Math.pow(2, attempt) * 1000;

            setTimeout(() => {
              // Возвращаем запрос в начало очереди (unshift), а не в конец
              this.queue.unshift(async () => {
                try {
                  resolve(await this.schedule(fn, attempt + 1));
                } catch (err) {
                  reject(err);
                }
              });
            }, delay);
          } else {
            // Если это другая ошибка или попытки исчерпаны — пробрасываем наверх
            reject(error);
          }
        }
      };

      if (this.tokens > 0 && this.queue.length === 0) {
        this.tokens--;
        execute();
      } else {
        this.queue.push(execute);
      }
    });
  }

  public destroy() {
    window.clearInterval(this.intervalId as number);
  }
}
