import { useIsConnectionRestored } from '@tonconnect/ui-react';
import { activeWalletSelector } from '../state';
import { WalletType } from '../types';
import { useLoadable } from './useLoadable';
import { useTonConnect } from './useTonConnect';

export function useActiveWallet() {
  const wallet = useLoadable(activeWalletSelector);
  const isConnectionRestored = useIsConnectionRestored();
  const { sender: tonConnectSender } = useTonConnect();

  return {
    wallet,
    walletRestored: wallet?.wallet == WalletType.tcsdk && isConnectionRestored ? wallet : wallet,
    sender: wallet?.wallet == WalletType.tcsdk ? tonConnectSender : undefined,
  };
}
